/**
 * Unique identifier structure (MVP doc §6). IDs are generated by the server only,
 * never reused and never edited after creation.
 */
export const ID_FORMATS = {
  USR: { yearly: false, pad: 6 }, // USR-000001
  CLT: { yearly: false, pad: 6 }, // CLT-000001 (client organisation)
  VND: { yearly: false, pad: 6 }, // VND-000001
  VNU: { yearly: false, pad: 6 }, // VNU-000001 (vendor user mapping)
  GP: { yearly: false, pad: 6 }, // GP-000001 (growth partner)
  LD: { yearly: true, pad: 6 }, // LD-2026-000001
  QT: { yearly: true, pad: 6 }, // QT-2026-000001 (+ -V1 suffix via quoteVersionId)
  BK: { yearly: true, pad: 6 }, // BK-2026-000001
  WO: { yearly: true, pad: 6 }, // WO-2026-000001
  CMP: { yearly: true, pad: 6 }, // CMP-2026-000001
  PAY: { yearly: true, pad: 6 }, // PAY-2026-000001
  TXI: { yearly: true, pad: 6 }, // TXI-2026-000001 (tax invoice)
  CRN: { yearly: true, pad: 6 }, // CRN-2026-000001 (credit note)
  ISS: { yearly: true, pad: 6 }, // ISS-2026-000001 (issue / complaint)
  PRF: { yearly: true, pad: 6 }, // PRF-2026-000001 (proof of display)
  EXP: { yearly: true, pad: 6 }, // EXP-2026-000001 (report export)
  NTF: { yearly: true, pad: 6 }, // NTF-2026-000001 (notification)
  TPL: { yearly: false, pad: 4 }, // TPL-0001 (notification template)
  SSH: { yearly: true, pad: 6 }, // SSH-2026-000001 (system setting history)
  RFL: { yearly: true, pad: 6 }, // RFL-2026-000001 (referral)
  CNL: { yearly: true, pad: 6 }, // CNL-2026-000001 (coin ledger row)
} as const;

export type IdPrefix = keyof typeof ID_FORMATS;

/** Counter key for a prefix: yearly prefixes restart each calendar year. */
export const counterKey = (prefix: IdPrefix, year: number) => (ID_FORMATS[prefix].yearly ? `${prefix}-${year}` : prefix);

export function formatId(prefix: IdPrefix, seq: number, year: number): string {
  const f = ID_FORMATS[prefix];
  const n = String(seq).padStart(f.pad, "0");
  return f.yearly ? `${prefix}-${year}-${n}` : `${prefix}-${n}`;
}

/** INV-<CAT>-000001 — category code e.g. HRD, LED, VEH, IND. */
export const formatInventoryId = (cat: string, seq: number) => `INV-${cat.toUpperCase()}-${String(seq).padStart(6, "0")}`;

export const quoteVersionId = (quoteId: string, version: number) => `${quoteId}-V${version}`;
